import{_ as r,a0 as i,w as l,s,I as n,x as e,a1 as o,A as u,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Ubuntu 22.04 LTS 和 20.04 LTS 之間的十大變化 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 22.04 LTS 和 20.04 LTS 之間的十大變化 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 22.04 LTS 和 20.04 LTS 之間的十大變化 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 22.04 LTS 和 20.04 LTS 之間的十大變化 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220419 Difference Between Ubuntu 22.04 and Ubuntu 20.04 LTS","title":"Ubuntu 22.04 LTS 和 20.04 LTS 之間的十大變化","tag":"202205","desc":""},"relativePath":"202205/20220419 Difference Between Ubuntu 22.04 and Ubuntu 20.04 LTS.md","filePath":"[post].md"}'),d={name:"202205/20220419 Difference Between Ubuntu 22.04 and Ubuntu 20.04 LTS.md"};function b(w,t,f,m,g,h){const a=i("Link");return l(),s("div",null,[t[26]||(t[26]=n("h1",{id:"ubuntu-22-04-lts-和-20-04-lts-之間的十大變化",tabindex:"-1"},[e("Ubuntu 22.04 LTS 和 20.04 LTS 之間的十大變化 "),n("a",{class:"header-anchor",href:"#ubuntu-22-04-lts-和-20-04-lts-之間的十大變化","aria-label":"Permalink to “Ubuntu 22.04 LTS 和 20.04 LTS 之間的十大變化”"},"​")],-1)),t[27]||(t[27]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202205/10/155537gcaaaupqayf5lnua.jpg",alt:""})],-1)),t[28]||(t[28]=n("blockquote",null,[n("p",null,"這裏為準備從 20.04 LTS 遷移到 22.04 LTS 的用户列出了十個最重要的變化。")],-1)),n("p",null,[t[2]||(t[2]=e("如果你是一位 ",-1)),o(a,{href:"https://www.debugpoint.com/2021/08/ubuntu-20-04-3-release/"},{default:u(()=>[...t[0]||(t[0]=[e("Ubuntu 20.04 LTS “Focal Fossa”",-1)])]),_:1}),t[3]||(t[3]=e(" 用户，並準備遷移到 ",-1)),o(a,{href:"https://www.debugpoint.com/2022/01/ubuntu-22-04-lts/"},{default:u(()=>[...t[1]||(t[1]=[e("Ubuntu 22.04 LTS “Jammy Jellyfish”",-1)])]),_:1}),t[4]||(t[4]=e("，這篇文章將為你提供一些指引。在這兩個 LTS 版本之間存在巨大的結構性變化，這在 LTS 分支中一般比較罕見。對比下來，不難發現本次更新一次性改變了大量的內容。",-1))]),t[29]||(t[29]=p('<p>瞭解了這一點之後，本文將針對普通用户關切的方面，列出十個發生根本性變化的特性，併為用户提供一些指引。</p><h3 id="ubuntu-22-04-lts-與-ubuntu-20-04-lts-–-特性變化" tabindex="-1">Ubuntu 22.04 LTS 與 Ubuntu 20.04 LTS – 特性變化 <a class="header-anchor" href="#ubuntu-22-04-lts-與-ubuntu-20-04-lts-–-特性變化" aria-label="Permalink to “Ubuntu 22.04 LTS 與 Ubuntu 20.04 LTS – 特性變化”">​</a></h3><h4 id="_1、徽標、顏色和-plymouth-動畫" tabindex="-1">1、徽標、顏色和 Plymouth 動畫 <a class="header-anchor" href="#_1、徽標、顏色和-plymouth-動畫" aria-label="Permalink to “1、徽標、顏色和 Plymouth 動畫”">​</a></h4><p>第一個你會注意到的視覺變化便是基調顏色相比早期的兩個“棕橙色”變得更“橙色”。同時 Canonical 對徽標進行了修改，這一點體現在開機時 Plymouth 動畫中。新的徽標乍一看會顯得有些怪異，但看久了會比較順眼，至少我認為這是一個十分與眾不同的徽標。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/01/New-Ubuntu-logo-and-playmouth.jpg" alt="New Ubuntu logo and Plymouth"></p><h4 id="_2、安裝" tabindex="-1">2、安裝 <a class="header-anchor" href="#_2、安裝" aria-label="Permalink to “2、安裝”">​</a></h4>',6)),n("p",null,[t[6]||(t[6]=e("Ubuntu 的默認安裝程序並沒有看到太多變化。我們其實更希望最新的 ",-1)),o(a,{href:"https://github.com/canonical/ubuntu-desktop-installer"},{default:u(()=>[...t[5]||(t[5]=[e("基於 Flutter 的安裝程序",-1)])]),_:1}),t[7]||(t[7]=e(" 能夠最終落地，但並沒有。基於此，整體安裝流程並未發生變化。我僅能夠觀察到對話框和按鈕的強調色發生了變化。從功能角度而言，安裝流程並未發生任何變化。",-1))]),t[30]||(t[30]=n("p",null,[n("img",{src:"https://www.debugpoint.com/wp-content/uploads/2022/04/Colour-differences-between-two-LTS-Versions.jpg",alt:"Colour differences between two LTS Versions"})],-1)),t[31]||(t[31]=n("h4",{id:"_3、鎖屏與登錄界面、桌面的初始界面以及壁紙",tabindex:"-1"},[e("3、鎖屏與登錄界面、桌面的初始界面以及壁紙 "),n("a",{class:"header-anchor",href:"#_3、鎖屏與登錄界面、桌面的初始界面以及壁紙","aria-label":"Permalink to “3、鎖屏與登錄界面、桌面的初始界面以及壁紙”"},"​")],-1)),t[32]||(t[32]=n("p",null,"鎖屏與登錄界面的漸變變得更為精細，密碼框採用了無邊框設計。初次登錄時的佈局和壁紙發生了很大的變化。桌面的 “家目錄” 快捷方式被重命名為 “Home”，而非你的用户名，但回收站快捷方式則移到了左側的任務欄中，並用分隔符與其他任務欄圖標隔開了。",-1)),n("p",null,[t[9]||(t[9]=e("除此之外，頂部狀態欄並未大改。系統托盤的菜單則進行了細微的修正，佈局更為寬鬆。這些變化主要來自於 ",-1)),o(a,{href:"https://www.debugpoint.com/2022/03/gnome-42-release/"},{default:u(()=>[...t[8]||(t[8]=[e("GNOME 42",-1)])]),_:1}),t[10]||(t[10]=e(" 的變化。",-1))]),t[33]||(t[33]=p('<p>日曆菜單並未發生變化。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Ubuntu-20.04-Vs-Ubuntu-22.04-Lock-and-Login-Screen-1024x431.jpg" alt="Ubuntu 20.04 Vs Ubuntu 22.04 – Login Screen"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Ubuntu-20.04-Vs-Ubuntu-22.04-Lock-Screen-1024x408.jpg" alt="Ubuntu 20.04 Vs Ubuntu 22.04 – Lock Screen"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Difference-between-Ubuntu-20.04-and-Ubuntu-22.04-default-look-1024x421.jpg" alt="Difference between Ubuntu 20.04 and Ubuntu 22.04 – default look"></p><h4 id="_4、桌面佈局和-gnome-版本升級" tabindex="-1">4、桌面佈局和 GNOME 版本升級 <a class="header-anchor" href="#_4、桌面佈局和-gnome-版本升級" aria-label="Permalink to “4、桌面佈局和 GNOME 版本升級”">​</a></h4><p>一個十分明顯的變化就是 GNOME 版本由 GNOME 3.36 升級到了 GNOME 42。這是所有升級用户都會看到的顯而易見的升級。Ubuntu 22.04 LTS 搭載的 GNOME 42 帶來了水平的工作區視圖以及水平的應用視圖。所以，遷移之後手勢從垂直轉變為水平會有一些不習慣，但用一段時間就好了。</p><p>如果你的設備是觸控屏的筆記本電腦或屏幕，經過一點學習之後，新的 GNOME 42 手勢會給你十分順滑的使用體驗。以下是桌面、應用和工作區的對比圖。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Activities-View-Difference-Ubuntu-20.04-and-22.04-1024x425.jpg" alt="Activities View Difference – Ubuntu 20.04 and 22.04"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Application-View-Difference-Ubuntu-20.04-and-22.04-1024x420.jpg" alt="Application View Difference – Ubuntu 20.04 and 22.04"></p><h4 id="_5、新的強調色與顯示樣式" tabindex="-1">5、新的強調色與顯示樣式 <a class="header-anchor" href="#_5、新的強調色與顯示樣式" aria-label="Permalink to “5、新的強調色與顯示樣式”">​</a></h4><p>有一個我非常喜歡的變化是最新的淺色和深色主題。早先 Ubuntu 有三個選擇：淺色、深色和混合（標準）。這在 GNOME 42 中發生了改變，因為其本身就帶有內置的淺色和深色模式。另一方面，它還引入了一個新的強調色選項（這並不是原本的 GNOME 42 帶來的），允許用户在全局進行自定義。</p><p>當然，你還不能像 KDE Plasma 一樣選擇自定義的強調色。這些變化大多來自於最近的 libadwaita 和 GTK4 對 GNOME Shell 和原生應用程序的移植。</p><p>而當你在 Ubuntu 22.04 LTS 中打開深色模式，它會自動應用於所有支持的應用，這是一個與 Ubuntu 20.04 LTS 十分顯著的區別。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Accent-Color-and-other-changes-1024x417.jpg" alt="Accent Color and other changes"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/How-Accent-colour-change-impact-looks-in-Ubuntu-22.04-LTS.jpg" alt="How Accent colour change impact looks in Ubuntu 22.04 LTS"></p><h4 id="_6、文件管理器" tabindex="-1">6、文件管理器 <a class="header-anchor" href="#_6、文件管理器" aria-label="Permalink to “6、文件管理器”">​</a></h4><p>在這個版本中，文件管理器的版本由 3.36.x 升級到了 42。區別是你能看到更為緊湊的設計、在文字和選項之間更為合理的佈局，以及頂部控制欄的小工具風格，這一切都歸功於 GTK4 和對底層錯誤的修復。文件中的地址欄有些不同，目錄之間有一個分隔符，而漢堡菜單在最後。當然，這些變化都較為細微，你可能不會感受到它們之間有什麼不同。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Files-Difference-Ubuntu-20.04-vs-22.04-1024x359.jpg" alt="Files Difference – Ubuntu 20.04 vs 22.04"></p><h4 id="_7、截圖工作流的變化" tabindex="-1">7、截圖工作流的變化 <a class="header-anchor" href="#_7、截圖工作流的變化" aria-label="Permalink to “7、截圖工作流的變化”">​</a></h4><p>另一個值得注意並且需要用户進行學習的是截圖方式的改變。它完全改變了。早先你按下 <code>Print Screen</code> 鍵時，會自動截圖並保存到圖片文件夾中。現在有了 GNOME 42 內置的截圖和錄屏工具，工作流程被完全改變。</p><p>當你在截圖時，你會發現有三個選項，你可以選擇某個區域、全屏截圖或者特定窗口。更重要的是，你還能選擇是否讓光標出現在截圖中，此外還有錄屏功能可選。選擇完成之後點擊“捕捉”按鈕，這張圖片將在被保存到圖片文件夾，並同時複製到你的剪切板。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/New-Screenshot-tool-in-Ubuntu-22.04-LTS.jpg" alt="New Screenshot tool in Ubuntu 22.04 LTS"></p><p>總體而言，相較於之前多了一個步驟。</p><p>在所有應用程序窗口頂部的右鍵菜單上，增添了一個新的截圖選項。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Take-Screenshot-option-in-top-bar-menu.jpg" alt="Take Screenshot option in top bar menu"></p><h4 id="_8、-firefox-瀏覽器成為了-snap-版本" tabindex="-1">8、 Firefox 瀏覽器成為了 Snap 版本 <a class="header-anchor" href="#_8、-firefox-瀏覽器成為了-snap-版本" aria-label="Permalink to “8、 Firefox 瀏覽器成為了 Snap 版本”">​</a></h4><p>此外，Firefox 瀏覽器在本次更新中變成了 Snap 版本。而此前在 20.04 LTS 中，Firefox 瀏覽器以 deb 包形式呈現。這對於一般用户而言區別不大。</p><p>但是 Firefox 瀏覽器的 Snap 沙箱運行模式使得安裝 GNOME 擴展工具時會產生問題，同時在同等硬件條件之下相較於之前的版本會顯得更慢。</p><p>這個最為常用的應用的 Snap 遷移所帶來的後續影響我們將拭目以待。</p><h4 id="_9、不同的設置窗口" tabindex="-1">9、不同的設置窗口 <a class="header-anchor" href="#_9、不同的設置窗口" aria-label="Permalink to “9、不同的設置窗口”">​</a></h4><p>在設置中出現了一個新的面板：多任務。多任務面板允許你調整觸發角以及激活窗口邊緣。此外你可以指定工作區的數量，並設置自動刪除空的工作區。而針對多顯示器用户，現在可以選擇僅在主屏幕上顯示工作區或是在所有屏幕上顯示工作區。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/New-Multitasking-Panel-in-Settings.jpg" alt="New Multitasking Panel in Settings"></p><h4 id="_10、主題和應用更新" tabindex="-1">10、主題和應用更新 <a class="header-anchor" href="#_10、主題和應用更新" aria-label="Permalink to “10、主題和應用更新”">​</a></h4><p>此外，軟件的變化帶來了不同的響應式外觀並能夠適應任何形式。軟件商店同時帶來了新的界面，包含了按照類別分類的軟件視圖以及“編輯之選”欄目。</p><p>應用詳情頁面變得更加易讀，重要的信息，例如總下載大小、評分、安全標記以及應用截圖都以更可辨別地方式呈現。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/GNOME-Software-Home-page-difference-1024x416.jpg" alt="GNOME Software – Home page difference"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/GNOME-Software-Details-page-difference-1024x417.jpg" alt="GNOME Software – Details page difference"></p><p>最後，這兩個版本的內部差異出現在軟件包、官方桌面環境主題和錯誤修正上。下面是對重要軟件包版本變化的一個對比：</p><div class="table-wrap"><table><thead><tr><th><strong>20.04</strong></th><th><strong>22.04</strong></th></tr></thead><tbody><tr><td>GCC 10.3</td><td>GCC 11.2</td></tr><tr><td>Hplip 3.20.3</td><td>Hplip 3.21.12</td></tr><tr><td>LibreOffice 6.4.7</td><td>LibreOffice 7.3.2</td></tr><tr><td>（未引入）</td><td>Pipewire 0.3.48</td></tr><tr><td>Python3 3.8.2</td><td>Python3 3.10.1</td></tr><tr><td>Samba 4.13</td><td>Samba 4.15</td></tr><tr><td>Systemd 245.4</td><td>Systemd 249.11</td></tr></tbody></table></div><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>總而言之，這是 Ubuntu LTS 分支歷次更新中變化最大的一次，不論是從視覺上還是特性角度。</p><p>我希望這個指南能夠令讀者瞭解兩個版本之間的主要區別，以及應當預期什麼樣的使用體驗。</p><p>祝好~</p><hr>',44)),n("p",null,[t[12]||(t[12]=e("via: ",-1)),o(a,{href:"https://www.debugpoint.com/2022/04/difference-ubuntu-22-04-20-04/"},{default:u(()=>[...t[11]||(t[11]=[e("https://www.debugpoint.com/2022/04/difference-ubuntu-22-04-20-04/",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=e("作者：",-1)),o(a,{href:"https://www.debugpoint.com/author/admin1/"},{default:u(()=>[...t[13]||(t[13]=[e("Arindam",-1)])]),_:1}),t[18]||(t[18]=e(" 選題：",-1)),o(a,{href:"https://github.com/lujun9972"},{default:u(()=>[...t[14]||(t[14]=[e("lujun9972",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),o(a,{href:"https://github.com/PeterPan0106"},{default:u(()=>[...t[15]||(t[15]=[e("PeterPan0106",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),o(a,{href:"https://github.com/wxy"},{default:u(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[23]||(t[23]=e("本文由 ",-1)),o(a,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創編譯，",-1)),o(a,{href:"https://linux.cn/"},{default:u(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const U=r(d,[["render",b]]);export{L as __pageData,U as default};
